import { randomUUID } from "node:crypto";
import { vi } from "vitest";
import { PrismaClient } from "@/generated/prisma/client";
import { PrismaPg } from "@prisma/adapter-pg";
import { createIsolatedDatabase } from "../helpers/foundation-db";

const mocks = vi.hoisted(() => ({
  db: null as unknown as PrismaClient,
  send: vi.fn(),
  gmail: vi.fn(),
  user: vi.fn(),
  auth: vi.fn(),
}));
vi.mock("@/lib/db", () => ({
  get db() {
    return mocks.db;
  },
}));
vi.mock("@/lib/session", () => ({ requireUser: mocks.user }));
vi.mock("@/auth", () => ({ auth: mocks.auth }));
vi.mock("next/cache", () => ({ revalidatePath: vi.fn() }));
vi.mock("@/lib/gmail", async (original) => ({
  ...(await original<typeof import("@/lib/gmail")>()),
  gmailForUser: mocks.gmail,
}));

export const boundary = mocks;

export async function usageFixture() {
  const fixture = await createIsolatedDatabase();
  try {
    for (const name of fixture.migrations) await fixture.apply(name);
    const db = new PrismaClient({
      adapter: new PrismaPg(
        { connectionString: fixture.url, max: 5 },
        { schema: fixture.schema },
      ),
    });
    boundary.db = db;
    boundary.send.mockResolvedValue({
      data: { id: "accepted-id", threadId: "accepted-thread" },
    });
    boundary.gmail.mockResolvedValue({
      email: "[REDACTED_EMAIL]",
      name: "Fixture",
      gmail: { users: { messages: { send: boundary.send } } },
    });
    return {
      db,
      close: async () => {
        await db.$disconnect();
        await fixture.cleanup();
      },
    };
  } catch (error) {
    await fixture.cleanup();
    throw error;
  }
}

export async function usageOwner(
  db: PrismaClient,
  options: { ready?: boolean; paid?: boolean } = {},
) {
  const now = new Date(Date.now());
  const user = await db.user.create({
    data: {
      email: `${randomUUID()}@example.test`,
      gmailAuthorized: true,
      encryptedRefreshToken: "[REDACTED_SECRET]",
      ...(options.ready === false
        ? {}
        : { usageBackfillVersion: 1, usageCutoverAt: now }),
      ...(options.paid
        ? {
            plan: "PAID",
            subscriptionStatus: "ACTIVE",
            dodoSubscriptionId: randomUUID(),
            currentPeriodStart: new Date(+now - 86400000),
            currentPeriodEnd: new Date(+now + 29 * 86400000),
          }
        : {}),
    },
  });
  const template = await db.template.create({
    data: {
      userId: user.id,
      name: "Fixture",
      subject: "Hello {{name}}",
      body: "Applying for {{role}}",
    },
  });
  async function input(count = 1) {
    const contacts = [];
    for (let i = 0; i < count; i++)
      contacts.push(
        await db.contact.create({
          data: {
            userId: user.id,
            name: "Ada",
            email: `${randomUUID()}@example.test`,
            jobRole: "Software Engineer",
          },
        }),
      );
    return {
      templateId: template.id,
      recipientIds: contacts.map((c) => c.id),
      recipientRoles: {},
      attachResume: false,
      idempotencyKey: randomUUID(),
    };
  }
  return { user, template, input };
}
export async function setGating(db: PrismaClient, enabled: boolean) {
  await db.systemControl.update({
    where: { key: "global" },
    data: { paidGatingEnabled: enabled, sendingEnabled: true },
  });
}
